module tb_TopModule;
    logic clk;
    logic a;
    logic b;
    logic out_assign;
    logic out_always_comb;
    logic out_always_ff;

    TopModule dut (
        .clk(clk),
        .a(a),
        .b(b),
        .out_assign(out_assign),
        .out_always_comb(out_always_comb),
        .out_always_ff(out_always_ff)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        a = 0;
        b = 0;
        #1;

        // Check initial state
        if (out_assign !== (a ^ b)) $fatal(1, "Assign mismatch at start");
        if (out_always_comb !== (a ^ b)) $fatal(1, "Comb mismatch at start");

        // Apply stimuli
        #10;
        a = 1; b = 0;
        #1;
        if (out_assign !== 1'b1) $fatal(1, "Assign mismatch");
        if (out_always_comb !== 1'b1) $fatal(1, "Comb mismatch");

        // Clock edge occurs
        #9; // total 20ns, clk posedge at 20
        // At posedge 20, a=1, b=0 -> out_always_ff should capture 1^0 = 1 on next cycle or at posedge?
        // Wait, always_ff updates on posedge clk. At posedge clk (t=20), a and b are 1 and 0. So at t=20 posedge, out_always_ff gets 1.
        #1;
        if (out_always_ff !== 1'b1) $fatal(1, "FF mismatch after posedge");

        a = 1; b = 1;
        #10; // clk posedge at 30. At t=30, a=1, b=1 -> out_always_ff gets 1^1 = 0.
        #1;
        if (out_assign !== 1'b0) $fatal(1, "Assign mismatch");
        if (out_always_comb !== 1'b0) $fatal(1, "Comb mismatch");
        if (out_always_ff !== 1'b0) $fatal(1, "FF mismatch");

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
